<template><AppShell><PageHeader :title="dispatch.dr_number" :subtitle="dispatch.customer.name"><div class="flex gap-2"><button class="btn-secondary" @click="post('mark-in-transit')">In Transit</button><button class="btn-primary" @click="post('mark-delivered')">Delivered</button><button class="btn-secondary" @click="post('cancel')">Cancel</button></div></PageHeader><div class="grid gap-6 lg:grid-cols-3"><div class="card p-5 lg:col-span-2"><StatusBadge :status="dispatch.status"/><div class="mt-5 space-y-3 border-l-4 border-gold pl-4"><div>Pending Dispatch</div><div>In Transit</div><div>Delivered</div></div></div><div class="card p-5"><h2 class="font-bold text-navy">Items</h2><div v-for="item in dispatch.items" :key="item.id" class="mt-3 flex justify-between"><span>{{ item.product.name }}</span><b>{{ item.quantity }}</b></div></div></div></AppShell></template><script>import { Inertia } from '@inertiajs/inertia'; import AppShell from '../../Components/AppShell.vue'; import PageHeader from '../../Components/PageHeader.vue'; import StatusBadge from '../../Components/StatusBadge.vue'; export default{components:{AppShell,PageHeader,StatusBadge},props:{dispatch:Object},methods:{post(action){Inertia.post('/dispatches/'+this.dispatch.id+'/'+action)}}}</script>